-- =====================================================================
-- Purple One - Actualizacion 09: clasificacion oficial de cada carrera
--
-- Ejecutar UNA vez sobre una base que ya tenga upgrade_08_canje_pitcoins.sql.
-- (Una instalacion nueva con schema.sql + seed.sql ya lo incluye.)
-- Agrega a cada participante su posicion oficial (NULL = no clasificado:
-- abandono o no tomo la salida) y su orden en la tabla oficial de
-- formula1.com. Solo datos oficiales: no toca pronosticos, PitCoins ni XP.
-- =====================================================================

USE purple1;

ALTER TABLE race_options
    ADD COLUMN finish_position TINYINT UNSIGNED NULL AFTER driver_id,
    ADD COLUMN finish_order TINYINT UNSIGNED NULL AFTER finish_position;

